:root {
  --col-bg: #e8f4f8;
  --col-border: #4a90a4;
  --col-header-bg: #4a90a4;
  --col-header-text: #ffffff;
  --col-name: #1a3a45;
  --col-latin: #5a7a85;
  --col-footer-bg: #d0eaf3;
  --col-stat-label: #5a7a85;
  --col-stat-value: #1a3a45;
  --col-divider: #4a90a4;
  --col-water-badge: #b0dce8;
  --col-water-text: #1a3a45;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
}

.fish-tag {
  background-color: var(--col-bg);
  border: 2px solid var(--col-border);
  border-radius: 12px;
  width: 240px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.tag-header {
  background-color: var(--col-header-bg);
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 6px 12px;
  box-sizing: border-box;
}

.tank-id {
  color: var(--col-header-text);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
}

.water-type {
  background-color: var(--col-water-badge);
  color: var(--col-water-text);
  font-size: 10px;
  font-weight: 600;
  padding: 2px 8px;
  border-radius: 20px;
}

.fish-icon {
  font-size: 40px;
  margin: 16px 0 8px;
  line-height: 1;
}

.fish-name {
  color: var(--col-name);
  font-size: 18px;
  font-weight: 700;
  margin: 0 0 4px;
  text-align: center;
}

.latin-name {
  color: var(--col-latin);
  font-size: 12px;
  font-style: italic;
  margin: 0 0 16px;
  text-align: center;
}

.tag-footer {
  background-color: var(--col-footer-bg);
  width: 100%;
  display: flex;
  justify-content: space-around;
  align-items: center;
  padding: 10px 8px;
  box-sizing: border-box;
}

.stat {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
}

.stat-label {
  color: var(--col-stat-label);
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.stat-value {
  color: var(--col-stat-value);
  font-size: 13px;
  font-weight: 700;
}

.divider {
  width: 1px;
  height: 28px;
  background-color: var(--col-divider);
  opacity: 0.4;
}
